import torch

def run(x, y):
    return x.fmod_(y)

def _dtype_from_context(ctx, name):
    return getattr(torch, ctx[f"{name}__dtype"])

def gen_inputs(ctx, device):
    y = torch.randn(
        ctx["y__shape"], dtype=_dtype_from_context(ctx, "y"), device=device
    )
    y = torch.where(y == 0, torch.ones_like(y), y)
    return {"y": y}
